        String logo_url = "/sdcard/shuquan/"+logo.split("\\.")[0]+".jpg";
        final File file = new File(logo_url);
        if (!file.exists()){
            Log.d("test","下载"+logo_url);
            HashMap<String, String> map = new HashMap<>();
