		resize(parent->width(), 0);
		arrange_right_down();

		w32 max_h=0;
		for (win_iter c=children.begin(); c!=children.end(); ++c)
		{
			if (c->y()-y()+c->height()>(sw32)max_h)
			{
				max_h=c->y()-y()+c->height();
			}
		}

		resize(parent->width(), (w16)max_h);
	}
}

