}


int vres_mig_nxt(vres_addr_t *nodes, int total, vres_addr_t *addr)
{
    int i;

    for (i = 0; i < total; i++)
        if (!memcmp(&nodes[i], &node_addr, sizeof(vres_addr_t)))
            break;
    if (i == total) {
        log_err("cannot find node");
        return -EINVAL;
    }
    if (i < total)
        i++;
    memcpy(addr, &nodes[i], sizeof(vres_addr_t));
    return 0;
}


