void push(int value){
    struct Node *newNode;
    newNode = malloc(sizeof(struct Node));
    newNode->data = value;

    if(top == NULL){
        newNode->next = NULL;
    }
    else{
        newNode->next  = top;              //Since top initially stores the address of previous node.//                                            
