class _LazyConnection(threading.local):
    def __init__(self, connection):
        self.connection = connection

    def connection(self):
        logging.info("get connection")
        return self.connection

    def close(self):
        logging.info("connection close")
        if not self.connection is None:
            self.connection.close()
            self.connection = None

    def cursor(self):
        logging.info("get cursor")
        if not self.connection is None:
            return self.connection.cursor()
        return None

    def commit(self):
        logging.info("commit")
        if not self.connection is None:
            self.connection.commit()

    def rollback(self):
        logging.info("rollback")
        if not self.connection is None:
            return self.connection.rollback()

_connection = None

class _Transactional(object):
    def commit(self):
        logging.info("commit")
        try:
            _connection.commit()
        except:
            logging.error("commit fail")
            _connection.rollback()

    def rollback(self):
        logging.info("rollback")
        _connection.rollback()

    def __enter__(self):
        logging.info("transaction start")

    def __exit__(self, exc_type, exc_val, exc_tb):
        logging.info("transaction finish")
        if exc_type is None:
            self.commit()
        else:
            self.rollback()

def _with_transaction(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        logging.info("call decorator")
        with _Transactional():
            return func(*args, **kwargs)
    return wrapper


