//-----------------------------------------------------------------------------
cpl_String& cpl_String::operator =(const char *s) { 
    char* tmp;
    if (s == 0) {
        tmp = strnew("");
    }    
    else {
        tmp = strnew(s);
    }    
    if (this->str != NULL) {
        free(this->str);
    }    
    this->str = tmp;
    return *this;
}

//-----------------------------------------------------------------------------
cpl_String& cpl_String::operator += (const char *s) {
    if (s == 0) {
        s = "";
    }    
    char *old = strnew(this->str);
    size_t lold = strlen(old), ls = strlen(s);
    free(this->str);
    this->str = (char*)malloc( lold + ls + 1 );
    memcpy(this->str, old, lold );
    memcpy(this->str+lold, s, ls );
    this->str[lold+ls] = '\0';
    free(old);
    return *this;
}

