int strrcmp(char *s, char *t) {
	size_t i = strlen(s) - 1;
	size_t j = strlen(t) - 1;
	while (s[i] == t[j] && i != 0 && j != 0) {
		i--;
		j--;
	}
	if (s[i] == t[j] && j == 0) {
		return 0;
	}
	return 1;
}

